import pandas as pd

manipulate_stock_prices = 'First'


def process_stock_prices(prices: pd.DataFrame, mode: str = manipulate_stock_prices,
                         freq: str = 'W') -> pd.DataFrame:
    """
    Transform a DataFrame of stock prices (DatetimeIndex, one column per ticker).

    Modes:
        'First'      - resample to `freq`, keeping the first price in each period
        'Last'       - resample to `freq`, keeping the last price in each period
        'Returns'    - daily percentage returns
        'LogReturns' - daily log returns
        'Normalize'  - rebase each series to start at 100
        'OHLC'       - resample to open/high/low/close per period
    """
    if not isinstance(prices.index, pd.DatetimeIndex):
        raise TypeError("prices must have a DatetimeIndex")

    prices = prices.sort_index()
    mode_key = mode.strip().lower()

    if mode_key == 'first':
        return prices.resample(freq).first().dropna(how='all')
    elif mode_key == 'last':
        return prices.resample(freq).last().dropna(how='all')
    elif mode_key == 'returns':
        return prices.pct_change().dropna(how='all')
    elif mode_key == 'logreturns':
        import numpy as np
        return np.log(prices / prices.shift(1)).dropna(how='all')
    elif mode_key == 'normalize':
        return prices.div(prices.bfill().iloc[0]).mul(100)
    elif mode_key == 'ohlc':
        return prices.resample(freq).ohlc().dropna(how='all')
    else:
        raise ValueError(f"Unknown mode: {mode!r}")


if __name__ == '__main__':
