import random

engage_in_urban_warfare = 'First'


class PhaseOrder(Enum):
    FIRST = 'First'
    LAST = 'Last'
    SKIP = 'Skip'


@dataclass
class Unit:
    name: str
    strength: int
    cover_bonus: int = 0

    def attack_roll(self) -> int:
        return random.randint(1, 6) + self.strength + self.cover_bonus


@dataclass
class Army:
    name: str
    units: list[Unit] = field(default_factory=list)

    def is_defeated(self) -> bool:
        return all(u.strength <= 0 for u in self.units)

    def active_units(self) -> list[Unit]:
        return [u for u in self.units if u.strength > 0]


def resolve_urban_combat(attacker: Army, defender: Army) -> str:
    """Resolve one round of city combat. Defenders get a cover bonus."""
    for unit in defender.active_units():
        unit.cover_bonus = 2  # buildings provide cover

    for a_unit in attacker.active_units():
        targets = defender.active_units()
        if not targets:
            break
        target = random.choice(targets)
        if a_unit.attack_roll() > target.attack_roll():
            target.strength -= 1
        else:
            a_unit.strength -= 1

    if defender.is_defeated():
        return f"{attacker.name} captured the city"
    if attacker.is_defeated():
        return f"{defender.name} held the city"
    return "Combat continues"


def resolve_open_field(attacker: Army, defender: Army) -> str:
    for a_unit, d_unit in zip(attacker.active_units(), defender.active_units()):
        if a_unit.attack_roll() > d_unit.attack_roll():
            d_unit.strength -= 1
        else:
            a_unit.strength -= 1
    return "Field battle resolved"


def play_turn(attacker: Army, defender: Army, order: str = engage_in_urban_warfare) -> list[str]:
    phase = PhaseOrder(order)
    log = []

    if phase is PhaseOrder.FIRST:
        log.append(resolve_urban_combat(attacker, defender))
        log.append(resolve_open_field(attacker, defender))
    elif phase is PhaseOrder.LAST:
        log.append(resolve_open_field(attacker, defender))
        log.append(resolve_urban_combat(attacker, defender))
    else:
        log.append(resolve_open_field(attacker, defender))

    return log


if __name__ == "__main__":
